SELECT P.ID, P.TIPO, P.JEITO, P.SERVE, P.QUANDO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, P.FAVORITA, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT COUNT(*) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) VEZES, (SELECT MAX(D.DIA) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) ULTIMA FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND P.ID > {{depois}} AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ({{fav}} = 0 OR P.FAVORITA = 1) AND ('{{jeito}}' = '' OR P.JEITO = '{{jeito}}') AND ('{{serve}}' = '' OR FIND_IN_SET('{{serve}}', P.SERVE) OR (LOCATE('.', '{{serve}}') = 0 AND CONCAT(',', P.SERVE) LIKE CONCAT('%,', '{{serve}}', '.%'))) AND ('{{quando}}' = '' OR FIND_IN_SET('{{quando}}', P.QUANDO)) ORDER BY P.ID LIMIT 500